"""Action-specific original Lockglass guides; preserve eight articulated idle poses."""
import json
from PIL import Image
import produce as p
UID='unit_embercourt_lockglass_writcasters'
B=p.ROOT/'art/animation/source/poses'/UID
IDENTITY=('Original LOCKGLASS WRITCASTER from supplied original painting. One human woman facing SCREEN RIGHT, exactly TWO arms and TWO legs. Original dark brown tied hair, red ribbons, pale face, red and ivory split court coat with gold trim, dark leggings, knee guards and brown boots. ONE original long bronze-and-darkwood lockglass rifle with SINGLE orange heated glass muzzle at the forward SCREEN RIGHT end and original red hanging writ tag. Near right hand keeps stock/trigger grip; far left hand supports forward barrel. Preserve original rifle length, glass chamber, wood stock, exact two grips, belt canister, coat, anatomy and painted fantasy style. No extra hands, rifles, muzzle tips or new weapons. ')
PLATE=(' Locked original three-quarter side camera, no cuts, turning, zoom or root travel. Flat magenta RGB255,0,255 background, no floor, scenery or cast shadow. Fixed boot contact plane y576. Planted boots stay grounded; all legitimate rifle, cloth and hair tips remain within generous margins. No projectiles, muzzle flash, beams, particles or rings; game renders projectile/effects separately. ')
def reference(index):
 f=dict(json.loads((B/'packing.json').read_bytes())['frames'][index]);f['source']=(B/f['source']).relative_to(p.ROOT).as_posix();f['alpha_noise_cutoff']=8
 if index==13:
  # The dropped rifle/tag projects in front of the fallen body. Ground the
  # near forearm/body contact, with that foreground footprint26 reference
  # pixels below it; anchoring to the lowest tag makes the corpse hover.
  im,o=p.source_pose(f,8);f['anchor']=[f['anchor'][0],round(f['anchor'][1]+(o[1]+im.height-26)/f['scale'])]
 return f
def recipe(clip,indices,guides,last,action,seed):
 out=p.SOURCE_DIR/(clip+'_h3_v1');out.mkdir(exist_ok=True)
 identity=IDENTITY.replace('with SINGLE orange heated glass muzzle at the forward SCREEN RIGHT end','with SINGLE orange heated glass muzzle at the barrel end, initially SCREEN RIGHT, rotating as one rigid object for the stock strike') if clip=='attack' else IDENTITY
 if clip=='death':identity=identity.replace('Near right hand keeps stock/trigger grip; far left hand supports forward barrel.','At initial ready, near hand grips stock/trigger and far hand supports barrel. Both hands naturally release the same rifle during the original falling guide; it settles intact in front of the corpse.').replace('exact two grips','original two hands and initial grips')
 plate=PLATE.replace('Fixed boot contact plane y576. Planted boots stay grounded;','Fixed anatomical ground reference y576. Initial boots planted; fallen body and dropped rifle settle into the original projected corpse footprint with near forearm/body contact grounded. Fallen boots and foreground rifle/tag need not share one image y;') if clip=='death' else PLATE
 c=dict(unit_id=UID,clip=clip,canvas=[960,640],anchor=[480,576],scale=.5,key_rgb=[255,0,255],seed=seed,references=[reference(i) for i in indices],guides=guides,last=last,prompt=(identity+action+plate).strip(),tiled_decode=dict(tile_size=512,overlap=64,temporal_size=16,temporal_overlap=4))
 p.write(out/'config.json',c);p.prepare(out,c);p.verify(out,c);print('Prepared',clip)
if __name__=='__main__':
 recipe('move',[14,2,3],[[36,1],[78,2]],0,'One reciprocal walking cycle IN PLACE. Near boot swings and plants then far boot swings and plants, with opposite knee bending and passing. Hips transfer weight over alternating planted boots. Both hands retain original lowered rifle grips while coat follows the gait. Return to exact initial ready. ',2026108701)
 recipe('attack',[14,4,5],[[34,1],[65,2]],0,'One physical close-range rifle-stock strike. Lift the ONE rifle sideways across chest into original windup, keeping both grips. Rotate the single rifle coherently until its orange muzzle is at SCREEN LEFT and wooden stock at SCREEN RIGHT as shown by the original windup/contact guides. Extend arms and lunge slightly SCREEN RIGHT through the original contact pose for one wooden rifle-stock shove, then draw same rifle back and recover exact ready. No firing and no repeated strike. ',2026108702)
 recipe('ranged',[14,8,9,10],[[32,1],[60,2],[88,3]],0,'One aimed rifle discharge gesture. Raise rifle, seat stock against shoulder with near trigger hand and far supporting hand, aim right. A single brief recoil drives rifle and shoulder backward together, elbows absorb recoil and then recover to lowered ready. Orange muzzle remains SINGLE fixed glass muzzle; no rendered shot or smoke. ',2026108703)
 recipe('hit',[14,7],[[46,1]],0,'One clear impact recoil: chest leans back and knees flex, head tips back briefly, both hands retain rifle. Boot stance braces the recoil. Recover upright to exact ready without falling, twisting around or changing rifle length. ',2026108704)
 recipe('defend',[14,6],[],1,'One continuous defensive brace. Lower onto original near knee with far boot planted forward and hold rifle horizontally across torso. Both hands maintain original grips, head bows slightly behind rifle guard. End held in original kneeling guard for final second, no return to idle. ',2026108705)
 recipe('cast',[14],[],0,'One physical non-magical allied acknowledgement. Left far hand stays supporting rifle barrel at low ready; near trigger hand releases stock briefly and raises open palm beside chest in a measured salute, elbow clearly bends, then returns to SAME stock grip. Maintain two arms, both feet grounded. No magic, spellcasting or new equipment. Return to exact initial ready. ',2026108706)
 recipe('death',[14,11,12,13],[[34,1],[70,2]],3,'One continuous grounded collapse. Knees buckle into original kneeling pose, torso loses support and leans forward, hand releases rifle onto ground as body rolls onto original side-rest corpse. TWO arms and TWO legs stay attached. Rifle rests flat in front, coat and ribbons settle. Hold exact original corpse for last second. No stand-up, shrinking or disintegration. ',2026108707)
 p.write(p.SOURCE_DIR/'delivery.json',dict(takes=[c+'_h3_v1' for c in ['move','attack','ranged','hit','defend','cast','death']],preserved_accepted_clips=['idle'],visual_review=dict(status='pending',notes='Original22 poses reviewed. Idle14-21 articulate hands and rifle with consistent two-arm/two-leg anatomy; preserve pixels and240ms timing. Seven dedicated H3 actions require personal full chronological and native acceptance.')))
 p.write(p.SOURCE_DIR/'runtime_registration.json',dict(unit_id=UID,reference_height=256,output_scale=.5,canvas=[960,640],ground_anchor=[480,576],ready_guide=reference(14),corpse_guide=reference(13),reason='Original per-source scale retained and fixed .5 extraction scale. Corpse contact adjusted once from original-pixel ground, never per-frame normalization.'))
